-- Update only the known historical demo notices. Preserve every custom text
-- and every non-demo salon. Appointment snapshots remain untouched.
UPDATE "SalonSettings"
SET "bookingTerms" = 'Демонстрационные условия: салон и услуги вымышлены. Запись сохраняется в локальной базе. При требуемой предоплате время временно резервируется; без оплаты бронь автоматически истекает. Онлайн-оплата пока не подключена. Если предоплата не требуется, запись подтверждается сразу. Договор с настоящим салоном не заключается. Перед запуском салон должен подготовить свои условия записи, отмены и переноса.',
    "updatedAt" = clock_timestamp()
WHERE "isDemo" = true AND "bookingTerms" = 'Демонстрационные условия: выбор и подтверждение на этом сайте показывают сценарий записи. Время не резервируется, договор с салоном не заключается. Перед настоящим запуском салон должен подготовить свои условия записи, отмены и переноса.';

UPDATE "SalonSettings"
SET "privacyTerms" = 'Демонстрационный текст об обработке данных. Для проверки используйте вымышленные контакты. Черновик формы находится в памяти вкладки. Контакты передаются локальному серверу и при создании записи сохраняются в базе вместе с условиями визита. Просмотр доступен по личной ссылке. Перед настоящим запуском салон должен подготовить согласованные документы об обработке персональных данных.',
    "updatedAt" = clock_timestamp()
WHERE "isDemo" = true AND "privacyTerms" = 'Демонстрационный текст об обработке данных. Для проверки используйте вымышленные контакты. Данные формы находятся в памяти вкладки и передаются локальному серверу для проверки без сохранения в базе. Перед настоящим запуском салон должен подготовить согласованные документы об обработке персональных данных.';
